async function run() {
  await Promise.all([
    figma.loadFontAsync({ family: 'Plus Jakarta Sans', style: 'Regular' }),
    figma.loadFontAsync({ family: 'Plus Jakarta Sans', style: 'Medium' }),
    figma.loadFontAsync({ family: 'Plus Jakarta Sans', style: 'SemiBold' }),
    figma.loadFontAsync({ family: 'Plus Jakarta Sans', style: 'Bold' }),
    figma.loadFontAsync({ family: 'Plus Jakarta Sans', style: 'ExtraBold' }),
  ]);

  const qrImage = figma.createImage(b64ToBytes(QR_B64));
  const qrHash = qrImage.hash;

  const mainPage = figma.root.children.find(function (p) { return p.name.indexOf('80 Screens') !== -1; }) || figma.root.children[0];
  const assetsPage = figma.root.children.find(function (p) { return p.name.indexOf('Brand Assets') !== -1; });

  const stats = { qrFixed: 0, quickActionsFixed: 0, plusFixed: 0, componentsFixed: 0 };
  let cLogo = null;

  if (assetsPage) {
    await figma.setCurrentPageAsync(assetsPage);

    const qrHolder = assetsPage.findOne(function (n) { return n.name === 'asset:qr_matrix'; });
    if (qrHolder && 'fills' in qrHolder) {
      qrHolder.fills = [{ type: 'IMAGE', imageHash: qrHash, scaleMode: 'FIT' }];
    }

    cLogo = assetsPage.findOne(function (n) { return n.type === 'COMPONENT' && n.name === 'PundiGo / Logo PG'; });

    const cNav = assetsPage.findOne(function (n) { return n.type === 'COMPONENT' && n.name === 'PundiGo / Bottom Nav Bar'; });
    if (cNav) {
      const homeCell = cNav.findOne(function (n) { return n.name === 'Nav / Beranda'; });
      if (homeCell && homeCell.children.length >= 2) {
        const oldIc = homeCell.children[0];
        homeCell.insertChild(0, makeSvg(SVG_HOME_SOLID, 22));
        oldIc.remove();
      }
      const scanCell = cNav.findOne(function (n) { return n.name === 'Nav / Scan QRIS'; });
      if (scanCell && scanCell.children.length >= 2) {
        const fab = scanCell.children[0];
        if (fab.type === 'FRAME') {
          fab.resize(50, 50);
          fab.cornerRadius = 25;
          fab.fills = [grad('#00A887', '#00796B')];
          fab.effects = [{ type: 'DROP_SHADOW', color: Object.assign({}, hex('#00897B'), { a: 0.35 }), offset: { x: 0, y: 4 }, radius: 12, spread: 0, visible: true, blendMode: 'NORMAL' }];
          while (fab.children.length > 0) fab.children[0].remove();
          fab.appendChild(makeSvg(SVG_SCAN_QR_FAB, 25));
        }
      }
      stats.componentsFixed++;
    }

    const cSmart = assetsPage.findOne(function (n) { return n.type === 'COMPONENT' && n.name === 'PundiGo / Smart Feature Cards'; });
    if (cSmart) {
      for (const card of cSmart.children) {
        if (card.type === 'FRAME' && card.children.length >= 2) {
          const ic = card.children[0];
          if (ic.type === 'RECTANGLE') {
            ic.resize(84, 58);
          }
        }
      }
      stats.componentsFixed++;
    }
  }

  await figma.setCurrentPageAsync(mainPage);

  const qaIconMap = {
    'Transfer': SVG_TRANSFER,
    'Top Up': SVG_TOPUP,
    'Minta Saldo': SVG_MINTA_SALDO,
    'Riwayat': SVG_RIWAYAT,
  };

  for (const frame of mainPage.children) {
    if (frame.type !== 'FRAME') continue;

    // A) FIX ALL QUICK ACTIONS BARS
    const texts = frame.findAllWithCriteria({ types: ['TEXT'] });
    for (const t of texts) {
      const svgCode = qaIconMap[t.characters];
      if (!svgCode) continue;
      const itemCol = t.parent;
      if (!itemCol || itemCol.type !== 'FRAME' || itemCol.layoutMode !== 'VERTICAL' || itemCol.children.length !== 2) continue;
      const iconBox = itemCol.children[0];
      if (iconBox.type !== 'FRAME' || iconBox.width < 36 || iconBox.width > 54) continue;

      iconBox.resize(44, 44);
      iconBox.cornerRadius = 22;
      iconBox.fills = [solid('#E8F8F5')];
      while (iconBox.children.length > 0) iconBox.children[0].remove();
      iconBox.appendChild(makeSvg(svgCode, t.characters === 'Top Up' ? 24 : 22));
      t.fills = [solid('#1E293B')];
      stats.quickActionsFixed++;
    }

    // B) FIX ALL QRIS SCREENS (15, 52, 71)
    if (frame.name.indexOf('15 - ') === 0 || frame.name.indexOf('52 - ') === 0 || frame.name.indexOf('71 - ') === 0) {
      const allFrames = frame.findAllWithCriteria({ types: ['FRAME'] });
      for (const f of allFrames) {
        const w = Math.round(f.width), h = Math.round(f.height);
        if ((w === 260 && h === 260) || (w === 240 && h === 240)) {
          f.fills = [solid('#FFFFFF')];
          f.cornerRadius = 18;
          f.strokes = [solid('#E2E8F0')];
          f.strokeWeight = 1.2;
          f.effects = [{ type: 'DROP_SHADOW', color: { r: 0.06, g: 0.09, b: 0.16, a: 0.06 }, offset: { x: 0, y: 4 }, radius: 14, spread: 0, visible: true, blendMode: 'NORMAL' }];
          while (f.children.length > 0) f.children[0].remove();
          const qrRect = figma.createRectangle();
          qrRect.name = 'QRIS Matrix Exact (PG Integrated)';
          qrRect.resize(w - 24, w - 24);
          qrRect.x = 12;
          qrRect.y = 12;
          qrRect.fills = [{ type: 'IMAGE', imageHash: qrHash, scaleMode: 'FIT' }];
          f.appendChild(qrRect);
          stats.qrFixed++;
        }
        if (Array.isArray(f.fills) && f.fills.length === 1 && f.fills[0].type === 'SOLID') {
          const c = f.fills[0].color;
          if (c.r > 0.75 && c.g < 0.25 && c.b < 0.25) {
            f.fills = [solid('#C61D3C')];
          }
        }
      }

      const qrActMap = {
        'Atur Nominal': SVG_EDIT_NOM,
        'Simpan QR': SVG_SAVE_QR,
        'Bagikan': SVG_SHARE_QR,
      };
      for (const t of texts) {
        const sCode = qrActMap[t.characters];
        if (!sCode) continue;
        const card = t.parent;
        if (card && card.type === 'FRAME' && card.children.length >= 2) {
          const oldIcon = card.children[0];
          card.insertChild(0, makeSvg(sCode, 22));
          oldIcon.remove();
        }
      }
    }

    // C) REBUILD SCREEN 08 (Penawaran PundiGo! Plus) 100% IDENTIK 8.png
    if (frame.name.indexOf('08 - ') === 0) {
      while (frame.children.length > 0) frame.children[0].remove();
      frame.fills = [solid('#FFFFFF')];

      const root = figma.createFrame();
      root.name = 'Plus Offer Layout';
      root.layoutMode = 'VERTICAL';
      root.itemSpacing = 0;
      root.fills = [];
      root.resize(480, 1180);
      frame.appendChild(root);

      const topBar = figma.createFrame();
      topBar.name = 'Top Bar';
      topBar.layoutMode = 'HORIZONTAL';
      topBar.primaryAxisAlignItems = 'SPACE_BETWEEN';
      topBar.counterAxisAlignItems = 'CENTER';
      topBar.paddingLeft = 24; topBar.paddingRight = 24; topBar.paddingTop = 16; topBar.paddingBottom = 16;
      topBar.fills = [solid('#F1F5F9')];
      root.appendChild(topBar);
      topBar.layoutSizingHorizontal = 'FILL';
      topBar.layoutSizingVertical = 'HUG';
      topBar.appendChild(makeText('PundiGo! Plus', 19, 'ExtraBold', '#0F172A'));
      if (cLogo) {
        const lg = cLogo.createInstance();
        lg.resize(34, 26);
        topBar.appendChild(lg);
      }

      const body = figma.createFrame();
      body.name = 'Content';
      body.layoutMode = 'VERTICAL';
      body.itemSpacing = 18;
      body.paddingLeft = 24; body.paddingRight = 24; body.paddingTop = 22; body.paddingBottom = 28;
      body.fills = [];
      root.appendChild(body);
      body.layoutSizingHorizontal = 'FILL';
      body.layoutSizingVertical = 'FILL';

      const okRow = figma.createFrame();
      okRow.layoutMode = 'HORIZONTAL'; okRow.itemSpacing = 10; okRow.counterAxisAlignItems = 'CENTER'; okRow.fills = [];
      body.appendChild(okRow); okRow.layoutSizingVertical = 'HUG'; okRow.layoutSizingHorizontal = 'HUG';
      const okCirc = figma.createFrame();
      okCirc.layoutMode = 'HORIZONTAL'; okCirc.primaryAxisAlignItems = 'CENTER'; okCirc.counterAxisAlignItems = 'CENTER';
      okCirc.resize(24, 24); okCirc.cornerRadius = 12; okCirc.fills = [solid('#D1FADF')];
      okCirc.appendChild(makeSvg(SVG_CHECK, 13));
      okRow.appendChild(okCirc);
      okRow.appendChild(makeText('PIN akun berhasil dibuat', 13.5, 'Bold', '#00897B'));

      body.appendChild(makeText('Kenalan dengan\nPundiGo! Plus', 28, 'ExtraBold', '#0F172A', { lh: 35 }));
      body.appendChild(makeText('Mau akses lebih? Tingkatkan akunmu dengan verifikasi identitas.', 13.5, 'Regular', '#64748B', { w: 432, lh: 20 }));

      const hero = figma.createFrame();
      hero.name = 'Plus Hero Card';
      hero.layoutMode = 'HORIZONTAL'; hero.itemSpacing = 18; hero.counterAxisAlignItems = 'CENTER';
      hero.paddingLeft = 22; hero.paddingRight = 22; hero.paddingTop = 26; hero.paddingBottom = 26;
      hero.cornerRadius = 20; hero.fills = [grad('#00BFA5', '#2979FF')];
      hero.effects = [{ type: 'DROP_SHADOW', color: Object.assign({}, hex('#00BFA5'), { a: 0.25 }), offset: { x: 0, y: 6 }, radius: 16, spread: 0, visible: true, blendMode: 'NORMAL' }];
      body.appendChild(hero);
      hero.layoutSizingHorizontal = 'FILL';
      hero.layoutSizingVertical = 'HUG';

      const walletVec = makeSvg(SVG_PLUS_WALLET);
      walletVec.resize(88, 78);
      hero.appendChild(walletVec);

      const hCol = figma.createFrame();
      hCol.layoutMode = 'VERTICAL'; hCol.itemSpacing = 6; hCol.fills = [];
      hero.appendChild(hCol);
      hCol.layoutSizingHorizontal = 'FILL';
      hCol.layoutSizingVertical = 'HUG';
      hCol.appendChild(makeText('Bisa transfer dengan akun Plus', 18, 'ExtraBold', '#FFFFFF', { w: 280, lh: 24 }));
      hCol.appendChild(makeText('Buka fitur transfer dan nikmati fitur PundiGo! lainnya.', 13.5, 'Regular', '#FFFFFF', { op: 0.94, w: 280, lh: 20 }));

      const req = figma.createFrame();
      req.name = 'Requirements Card';
      req.layoutMode = 'VERTICAL'; req.itemSpacing = 18;
      req.paddingLeft = 22; req.paddingRight = 22; req.paddingTop = 22; req.paddingBottom = 22;
      req.cornerRadius = 20; req.fills = [solid('#FFFFFF')];
      req.strokes = [solid('#E2E8F0')]; req.strokeWeight = 1.2;
      body.appendChild(req);
      req.layoutSizingHorizontal = 'FILL';
      req.layoutSizingVertical = 'HUG';

      const reqHead = figma.createFrame();
      reqHead.layoutMode = 'VERTICAL'; reqHead.itemSpacing = 4; reqHead.fills = [];
      req.appendChild(reqHead); reqHead.layoutSizingHorizontal = 'FILL'; reqHead.layoutSizingVertical = 'HUG';
      reqHead.appendChild(makeText('Untuk jadi Plus, siapkan:', 17, 'ExtraBold', '#0F172A'));
      reqHead.appendChild(makeText('Verifikasi identitas saat kamu siap.', 13, 'Regular', '#64748B'));

      const addReqItem = function (svgStr, title, sub) {
        const row = figma.createFrame();
        row.layoutMode = 'HORIZONTAL'; row.itemSpacing = 16; row.counterAxisAlignItems = 'CENTER'; row.fills = [];
        req.appendChild(row); row.layoutSizingHorizontal = 'FILL'; row.layoutSizingVertical = 'HUG';
        const ib = figma.createFrame();
        ib.layoutMode = 'HORIZONTAL'; ib.primaryAxisAlignItems = 'CENTER'; ib.counterAxisAlignItems = 'CENTER';
        ib.resize(50, 50); ib.cornerRadius = 14; ib.fills = [solid('#EFF6FF')];
        ib.appendChild(makeSvg(svgStr, 25));
        row.appendChild(ib);
        const tc = figma.createFrame();
        tc.layoutMode = 'VERTICAL'; tc.itemSpacing = 3; tc.fills = [];
        row.appendChild(tc); tc.layoutSizingHorizontal = 'FILL'; tc.layoutSizingVertical = 'HUG';
        tc.appendChild(makeText(title, 15.5, 'Bold', '#0F172A'));
        tc.appendChild(makeText(sub, 13, 'Regular', '#64748B'));
      };
      addReqItem(SVG_KTP_REQ, 'KTP milikmu', 'Scan atau foto KTP yang jelas.');
      addReqItem(SVG_FACE_REQ, 'Wajah / selfie', 'Verifikasi wajah untuk cocokkan identitas.');

      const noteWrap = figma.createFrame();
      noteWrap.layoutMode = 'VERTICAL'; noteWrap.itemSpacing = 14; noteWrap.paddingTop = 10; noteWrap.counterAxisAlignItems = 'CENTER'; noteWrap.fills = [];
      body.appendChild(noteWrap); noteWrap.layoutSizingHorizontal = 'FILL'; noteWrap.layoutSizingVertical = 'HUG';

      const disc = makeText('Bisa lanjut tanpa upgrade sekarang.\nTingkatkan ke Plus nanti saat kamu siap.', 13, 'Regular', '#64748B', { align: 'CENTER', lh: 20 });
      noteWrap.appendChild(disc); disc.layoutSizingHorizontal = 'FILL';

      const cta = figma.createFrame();
      cta.name = 'CTA Tingkatkan ke Plus';
      cta.layoutMode = 'HORIZONTAL'; cta.itemSpacing = 8; cta.primaryAxisAlignItems = 'CENTER'; cta.counterAxisAlignItems = 'CENTER';
      cta.paddingTop = 17; cta.paddingBottom = 17; cta.cornerRadius = 16;
      cta.fills = [grad('#00BFA5', '#2979FF')];
      cta.effects = [{ type: 'DROP_SHADOW', color: Object.assign({}, hex('#00BFA5'), { a: 0.3 }), offset: { x: 0, y: 5 }, radius: 14, spread: 0, visible: true, blendMode: 'NORMAL' }];
      noteWrap.appendChild(cta); cta.layoutSizingHorizontal = 'FILL'; cta.layoutSizingVertical = 'HUG';
      cta.appendChild(makeText('Tingkatkan ke Plus', 16, 'Bold', '#FFFFFF'));
      cta.appendChild(makeSvg(SVG_ARROW_R, 17));

      const later = makeText('Nanti saja', 15.5, 'Bold', '#00A887', { align: 'CENTER' });
      noteWrap.appendChild(later); later.layoutSizingHorizontal = 'FILL';

      stats.plusFixed++;
    }
  }

  figma.notify(
    'Selesai! QR Asli: ' + stats.qrFixed + ' layar | Quick Actions: ' + stats.quickActionsFixed + ' ikon | Plus Offer: ' + stats.plusFixed + ' layar | Master Komponen: ' + stats.componentsFixed,
    { timeout: 6000 }
  );
  figma.closePlugin();
}

run().catch(function (err) {
  figma.notify('Error: ' + (err && err.message ? err.message : String(err)), { error: true });
  figma.closePlugin();
});
